   EXECUTE format('REVOKE ALL ON ai_latency_private.final_decision_codings FROM %I',r);
   EXECUTE format('REVOKE ALL ON FUNCTION ai_latency_private.admin_code_final(uuid,text,text,integer,text,uuid) FROM %I',r);
  END IF;
 END LOOP;
END $$;
